    date = E.get(date);
    tz = (tz||E.local_tz).replace(':', '');
    opt = opt||{};
    var timezone = +tz.slice(1, 3)*E.ms.HOUR+tz.slice(3, 5)*E.ms.MIN;
    var sign = tz.slice(0, 1) == '+' ? 1 : -1;
